Use the `pg` library's `Pool` class — it's the standard approach:

```js
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // Pool sizing
  max: 20,                    // max connections (default: 10)
  min: 2,                     // keep idle connections ready
  // Timeouts (all in ms)
  connectionTimeoutMillis: 5000,   // fail fast if can't acquire connection
  idleTimeoutMillis: 30000,        // release idle connections after 30s
  statement_timeout: 10000,        // kill queries running >10s
  query_timeout: 10000,            // client-level query timeout
});

// Global error handler — prevents unhandled rejections from idle clients
pool.on('error', (err) => {
  console.error('Idle client error', err);
});
```

**Querying with proper release:**

```js
// Option A: pool.query() — handles acquire/release automatically
async function getUser(id) {
  const { rows } = await pool.query('SELECT * FROM users WHERE id = $1', [id]);
  return rows[0];
}

// Option B: explicit client — needed for transactions
async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [amount, fromId]);
    await client.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [amount, toId]);
    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();  // always release, even on error
  }
}
```

**Shutdown handling:**

```js
process.on('SIGTERM', async () => {
  await pool.end();  // drains pool before exit
  process.exit(0);
});
```

**Key things to get right:**

- Always use `$1, $2` parameterized queries — never string interpolation (SQL injection)
- `pool.query()` is safe for one-off queries; use explicit `connect()`/`release()` only for transactions
- The `pool.on('error')` handler is required — without it, an error on an idle connection crashes the process
- Set `statement_timeout` at the DB level too (in `postgresql.conf` or per-role) as a backstop
